"""Stage count-neutral exact-row replacements only; never edits scenery/Studio/catalog."""
from pathlib import Path
import json,math,hashlib,subprocess,importlib.util,numpy as np
N=Path(__file__).resolve().parents[1];E=N.parents[1];P=N/'world-project';R=N/'review/art/birch';W=100800.;D=W*2818/5009

def mod(name,p):
 s=importlib.util.spec_from_file_location(name,p);m=importlib.util.module_from_spec(s);s.loader.exec_module(m);return m
geo=mod('geo_birch_stage',E/'build/woodland-detail-2026-11-19/tools/review_forest_layout.py');art=json.loads((R.parent/'ART_PATCH.json').read_text());models=json.loads((R/'BIRCH_MODELS.json').read_text())['records'];files={p.name:p.read_text().splitlines()for p in(P/'scenery').glob('*.txt')};camp=np.array([-11988.,5172.]);g={r['alias']:geo.geometry(P/'models'/(r['stem']+'_near.glb'))[0]for r in models}
paths=json.loads((P/'opening/first-journey.routes.json').read_text())['paths'];segments=[]
for pts in paths.values():
 a=np.array(pts)[:,[0,2]];segments.extend(zip(a[:-1],a[1:]))
segments=np.array(segments);near=[r for r in art['changed_rows']if r['family']in ['pine_young','broadleaf']];near.sort(key=lambda r:np.linalg.norm(np.array([(float(r['after'].split()[1])-.5)*W,(float(r['after'].split()[2])-.5)*D])-camp));far=sorted(art['far_treeline_replacements'],key=lambda r:math.atan2((float(r['after'].split()[2])-.5)*D-camp[1],(float(r['after'].split()[1])-.5)*W-camp[0]));selected=near[:6]+[far[i]for i in np.linspace(0,len(far)-1,12,dtype=int)];proposed=[];points=[]
for j,item in enumerate(selected):
 name=Path(item['file']).name;before=files[name][item['line']-1];q=before.split();x=(float(q[1])-.5)*W;z=(float(q[2])-.5)*D;yaw=float(q[3]);rec=models[j%2];soil=rec['soil_plane_glb_y'];target=(6.4 if j%2==0 else 10.7)if j<6 else(min(18.,item['height_above_soil_m'])if j%2==0 else item['height_above_soil_m']);scale=target/(rec['authored_full_height_m']-soil);assert .15<=scale<=2.;rot=geo.rot(yaw,0,0);cxz=np.array(rec['soil_sections'][0]['center_xz']);cc=np.array([cxz[0],0,cxz[1]])*scale@rot.T;center=np.array([x,z])+cc[[0,2]];v=g[rec['alias']]*scale@rot.T;low=v[v[:,1]<soil*scale+2.4];radius=np.linalg.norm(low[:,[0,2]],axis=1).max();clear=geo.dist(np.array([x,z]),segments)-radius
 if clear<3.2:continue
 support=[center,center+[.4,0],center+[-.4,0],center+[0,.4],center+[0,-.4]];start=len(points);points.extend(support);proposed.append({'file':'scenery/'+name,'line':item['line'],'before':before,'alias':rec['alias'],'stem':rec['stem'],'x':x,'z':z,'yaw':yaw,'scale':scale,'soil':soil,'sample_start':start,'height_above_soil_m':target,'route_clearance_m':float(clear),'soil_center_world_xz':center.tolist(),'kind':'near_birch'if j<6 else'far_birch'})
np.asarray(points,'<f8').tofile(R/'placement.points.bin');helper=N/'tools/art_native_ground_sampler';run=subprocess.run([str(helper),str(P),str(R/'placement.points.bin'),str(R/'placement.samples.bin')],capture_output=True,text=True);(R/'placement-sampler.log').write_text(run.stdout+run.stderr);run.check_returncode();samples=np.fromfile(R/'placement.samples.bin','<f8').reshape(-1,8);changes=[];rejected=[]
for item in proposed:
 a=samples[item['sample_start']:item['sample_start']+5];y=float(a[0,2]-item['soil']*item['scale'])
 if a[:,4].any()or max(a[:,2])-min(a[:,2])>.33 or y<.1:rejected.append(item|{'reason':'wet or uneven support'});continue
 row=' '.join([item['alias'],f'{item["x"]/W+.5:.13f}',f'{item["z"]/D+.5:.13f}',f'{item["yaw"]:.7f}',f'{item["scale"]:.9f}','0','0','0','0','0','1','1','1',f'{y:.9f}','wind','1','1']);assert len(' '.join(row.split()[:14]))<=256 and len(row)<=320;changes.append(item|{'after':row,'pivot_y':y,'soil_height_error_m':y+item['soil']*item['scale']-float(a[0,2]),'all_support_points_native_dry':True,'native_base_scale_valid':True})
assert len(changes)>=12
out={'passed':True,'staged_only':True,'candidate_scenery_changed':False,'tree_count_change':0,'required_alias_patch':str(R.parent/'STUDIO_BIRCH_PATCH.json'),'required_collision_patch':str(R.parent/'COLLISION_BIRCH_PATCH.json'),'apply_order':['Install owned models (done)','Merge new bark-only collision catalog rows','Merge new Studio aliases','Apply exact scenery before→after rows','Native visual/performance and collision review'],'changes':changes,'rejected':rejected,'sampler_sha256':hashlib.sha256(helper.read_bytes()).hexdigest(),'preimage_sha256':{f:hashlib.sha256((P/f).read_bytes()).hexdigest()for f in {x['file']for x in changes}}};(R.parent/'SCENERY_BIRCH_PATCH.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'passed':True,'staged_replacements':len(changes),'near':sum(c['kind']=='near_birch'for c in changes),'far':sum(c['kind']=='far_birch'for c in changes),'scenery_edited':False,'maximum_base_scale':max(c['scale']for c in changes)}))
